export const generateReport = (employees) => {
  const reportData = employees.map(emp => ({
    Nombre: emp.name,
    Puesto: emp.position,
    Departamento: emp.department,
    'Hora de Entrada': emp.entryTime,
    'Minutos de Tardanza': emp.tardiness,
    'Código QR': emp.qrCode
  }));
  
  const csvContent = "data:text/csv;charset=utf-8," 
    + "Nombre,Puesto,Departamento,Hora de Entrada,Minutos de Tardanza,Código QR\n"
    + reportData.map(e => Object.values(e).join(",")).join("\n");
  
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", "reporte_asistencia_completo.csv");
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export const getStatsSummary = (employees) => ({
  totalEmployees: employees.length,
  punctualEmployees: employees.filter(emp => emp.tardiness === 0).length,
  lateEmployees: employees.filter(emp => emp.tardiness > 0).length,
  averageTardiness: employees.length > 0 
    ? Math.round(employees.reduce((acc, emp) => acc + emp.tardiness, 0) / employees.length)
    : 0
});
